(397,10,'faq','q1','text','Pregunta 1','¿Tengo un escritorio asignado?','','',76,NULL),
(398,10,'faq','a1','richtext','Respuesta 1','No. Con Coworking puedes elegir un lugar disponible dentro de las áreas compartidas cada vez que trabajes desde Aldea.','','',77,NULL),
(399,10,'faq','q2','text','Pregunta 2','¿Cuál es la diferencia entre Coworking y Escritorio Privado?','','',78,NULL),
(400,10,'faq','a2','richtext','Respuesta 2','Coworking te permite trabajar desde los lugares disponibles en un área compartida. Con Escritorio Privado tienes una estación de trabajo fija y exclusiva para ti.','','',79,NULL),
(401,10,'faq','q3','text','Pregunta 3','¿Cuál es la diferencia entre Coworking y Oficina Privada?','','',80,NULL),
(402,10,'faq','a3','richtext','Respuesta 3','Coworking utiliza áreas de trabajo compartidas. Una Oficina Privada es un espacio cerrado y exclusivo para ti o tu equipo.','','',81,NULL),
(403,10,'faq','q4','text','Pregunta 4','¿Cuál es el plazo mínimo?','','',82,NULL),
(404,10,'faq','a4','richtext','Respuesta 4','Las membresías de Coworking pueden contratarse desde 1 mes.','','',83,NULL),
(405,10,'faq','q5','text','Pregunta 5','¿Puedo utilizar las salas de juntas?','','',84,NULL),
(406,10,'faq','a5','richtext','Respuesta 5','Sí. Las membresías incluyen acceso a salas de juntas de acuerdo con las condiciones y créditos correspondientes a la membresía contratada.','','',85,NULL),
(407,10,'faq','q6','text','Pregunta 6','¿Qué servicios están incluidos?','','',86,NULL),
(408,10,'faq','a6','richtext','Respuesta 6','Tienes acceso a internet, mobiliario, áreas comunes y diferentes servicios Aldea. Los beneficios específicos pueden variar según sede y membresía.','','',87,NULL),
(409,10,'faq','q7','text','Pregunta 7','¿Puedo recibir visitas?','','',88,NULL),
(410,10,'faq','a7','richtext','Respuesta 7','Sí, puedes recibir visitas de acuerdo con las políticas de acceso de cada sede. Para reuniones privadas recomendamos utilizar las salas de juntas.','','',89,NULL),
(411,10,'faq','q8','text','Pregunta 8','¿Cuánto cuesta Coworking?','','',90,NULL),
(412,10,'faq','a8','richtext','Respuesta 8','El precio depende de la sede y condiciones de contratación. Selecciona tu ciudad o solicita una cotización para conocer la membresía disponible.','','',91,NULL),
