(570,12,'faq','q1','text','Pregunta 1','¿Puedo utilizar la dirección de Aldea como domicilio fiscal?','','',62,NULL),
(571,12,'faq','a1','richtext','Respuesta 1','Sí. El Domicilio Virtual permite utilizar la dirección contratada como domicilio fiscal de acuerdo con las condiciones y documentación correspondiente.','','',63,NULL),
(572,12,'faq','q2','text','Pregunta 2','¿También puedo utilizarla como domicilio comercial?','','',64,NULL),
(573,12,'faq','a2','richtext','Respuesta 2','Sí. Puedes utilizarla como dirección comercial para dar presencia profesional a tu empresa.','','',65,NULL),
(574,12,'faq','q3','text','Pregunta 3','¿Tengo una oficina física incluida?','','',66,NULL),
(575,12,'faq','a3','richtext','Respuesta 3','No. Domicilio Virtual no incluye una Oficina Privada ni un espacio de trabajo permanente.','','',67,NULL),
(576,12,'faq','q4','text','Pregunta 4','¿Qué pasa cuando recibo correspondencia o paquetería?','','',68,NULL),
(577,12,'faq','a4','richtext','Respuesta 4','Nuestro equipo la recibe y te notifica para que puedas recogerla de acuerdo con las políticas de la sede.','','',69,NULL),
(578,12,'faq','q5','text','Pregunta 5','¿Puedo utilizar salas de juntas?','','',70,NULL),
(579,12,'faq','a5','richtext','Respuesta 5','Sí. La membresía contempla acceso a salas de juntas de acuerdo con las horas, créditos o condiciones contratadas.','','',71,NULL),
(580,12,'faq','q6','text','Pregunta 6','¿Cuál es el plazo mínimo de contratación?','','',72,NULL),
(581,12,'faq','a6','richtext','Respuesta 6','El plazo mínimo de Domicilio Virtual es de 12 meses.','','',73,NULL);
