(953,17,'faq','q1','text','Pregunta 1','¿Dónde está Aldea Galerías?','','',81,NULL),
(954,17,'faq','a1','richtext','Respuesta 1','Aldea Galerías se encuentra en Av. Independencia #1861, Ed. 5, Galerías Business Square, C.P. 20120, Aguascalientes, Ags.','','',82,NULL),
(955,17,'faq','q2','text','Pregunta 2','¿Qué espacios puedo contratar?','','',83,NULL),
(956,17,'faq','a2','richtext','Respuesta 2','Contamos con Oficina Privada, Coworking, Escritorio Privado y Domicilio Virtual, sujetos a disponibilidad.','','',84,NULL),
(957,17,'faq','q3','text','Pregunta 3','¿Las oficinas vienen amuebladas?','','',85,NULL),
(958,17,'faq','a3','richtext','Respuesta 3','Sí. Las Oficinas Privadas se entregan con mobiliario para que puedas empezar a trabajar desde el primer día.','','',86,NULL),
(959,17,'faq','q4','text','Pregunta 4','¿Cuál es el plazo mínimo de contratación?','','',87,NULL),
(960,17,'faq','a4','richtext','Respuesta 4','Las membresías de espacios de trabajo pueden contratarse desde 1 mes, con opciones de mayor plazo según la solución y disponibilidad.','','',88,NULL),
(961,17,'faq','q5','text','Pregunta 5','¿Puedo utilizar salas de juntas?','','',89,NULL),
(962,17,'faq','a5','richtext','Respuesta 5','Sí. El acceso depende de las condiciones y créditos incluidos en la membresía contratada.','','',90,NULL),
(963,17,'faq','q6','text','Pregunta 6','¿Aldea Galerías cuenta con estacionamiento?','','',91,NULL),
(964,17,'faq','a6','richtext','Respuesta 6','Sí. La sede cuenta con estacionamiento en Galerías Business Square. [PENDIENTE: confirmar las condiciones finales de estacionamiento.]','','',92,NULL),
(965,17,'faq','q7','text','Pregunta 7','¿Puedo recibir clientes y visitantes?','','',93,NULL),
(966,17,'faq','a7','richtext','Respuesta 7','Sí. Aldea cuenta con recepción y espacios para atender visitantes de acuerdo con las políticas de acceso de la sede.','','',94,NULL),
