(1076,18,'form','title','text','Titulo','Cuéntanos tu proyecto','Tell us about your project','',109,NULL),
(1077,18,'form','text','richtext','Texto','Compártenos los datos principales de tu operación y nuestro equipo corporativo se pondrá en contacto contigo para conocer el proyecto a detalle.','Share the main details of your operation and our corporate team will get in touch to go through the project.','',110,NULL),
(1078,18,'form','boton','text','Texto del boton','Hablar con nuestro equipo corporativo','Talk to our corporate team','',111,NULL),
(1079,18,'faq','title','text','Titulo','Preguntas frecuentes','Frequently asked questions','',112,NULL),
(1080,18,'faq','q1','text','Pregunta 1','¿Para qué tamaño de empresa está diseñada esta solución?','','',113,NULL),
(1081,18,'faq','a1','richtext','Respuesta 1','Oficinas Corporativas está enfocada en proyectos para equipos de más de 100 personas.','','',114,NULL),
(1082,18,'faq','q2','text','Pregunta 2','¿Cuál es el plazo mínimo?','','',115,NULL),
(1083,18,'faq','a2','richtext','Respuesta 2','Los proyectos se desarrollan a partir de contratos de 36 meses, dependiendo del alcance y características de la operación.','','',116,NULL),
(1084,18,'faq','q3','text','Pregunta 3','¿El proyecto tiene que estar dentro de una sede Aldea?','','',117,NULL),
(1085,18,'faq','a3','richtext','Respuesta 3','No. Podemos buscar y evaluar un inmueble específicamente para las necesidades del proyecto.','','',118,NULL),
(1086,18,'faq','q4','text','Pregunta 4','¿Aldea puede ayudar a encontrar el inmueble?','','',119,NULL),
(1087,18,'faq','a4','richtext','Respuesta 4','Sí. La búsqueda y evaluación del inmueble puede formar parte del desarrollo integral del proyecto.','','',120,NULL),
(1088,18,'faq','q5','text','Pregunta 5','¿Qué incluye una Oficina Corporativa a la Medida?','','',121,NULL),
(1089,18,'faq','a5','richtext','Respuesta 5','El alcance puede integrar inmueble, arquitectura, adecuaciones, mobiliario, infraestructura, tecnología y servicios operativos según las necesidades definidas con el cliente.','','',122,NULL),
(1090,18,'faq','q6','text','Pregunta 6','¿Qué puedo personalizar?','','',123,NULL),
(1091,18,'faq','a6','richtext','Respuesta 6','La distribución, arquitectura, mobiliario, infraestructura, tecnología, identidad y servicios pueden desarrollarse de acuerdo con los requerimientos del proyecto.','','',124,NULL),
(1092,18,'faq','q7','text','Pregunta 7','¿Qué servicios puede operar Aldea?','','',125,NULL),
(1093,18,'faq','a7','richtext','Respuesta 7','Podemos integrar servicios como recepción, limpieza, mantenimiento, tecnología, seguridad, control de acceso, estacionamiento y otros requerimientos definidos para la operación.','','',126,NULL),
(1094,18,'faq','q8','text','Pregunta 8','¿Cuánto tarda un proyecto?','','',127,NULL),
(1095,18,'faq','a8','richtext','Respuesta 8','El tiempo depende del inmueble, superficie, alcance y adecuaciones necesarias. Después del diagnóstico desarrollamos un cronograma específico para cada proyecto.','','',128,NULL),
(1096,18,'faq','q9','text','Pregunta 9','¿Cómo se estructura el costo?','','',129,NULL),
(1097,18,'faq','a9','richtext','Respuesta 9','El proyecto puede integrar el uso del inmueble, adecuaciones, mobiliario, infraestructura y servicios dentro de una sola renta mensual durante el plazo contratado.','','',130,NULL),
