INSERT INTO `solutions` (`id`,`slug`,`title_es`,`title_en`,`excerpt_es`,`excerpt_en`,`body_es`,`body_en`,`features_es`,`features_en`,`hero_image`,`gallery`,`seo_title_es`,`seo_desc_es`,`seo_title_en`,`seo_desc_en`,`in_menu`,`sort`,`published`,`updated_at`,`hero_image_alt`,`includes_es`,`includes_en`) VALUES
(1,'oficina-privada','Oficina Privada','Private Office','Una oficina cerrada, amueblada y exclusiva para ti o tu equipo.','A private, furnished office just for you or your team.','Tu propio espacio privado y totalmente equipado, listo para trabajar desde el primer dia. Ideal para equipos que buscan privacidad, imagen profesional y la flexibilidad de escalar segun crece su empresa.',NULL,'["Oficina privada y amueblada","Capacidad de 1 a 100+ personas","Todos los servicios incluidos","Salas de juntas y areas comunes","Contratos flexibles"]',NULL,'/img/sedes/leon/oficina-privada.webp','["/img/sedes/leon/oficina-privada.webp","/img/oficina-privada/op-1.webp","/img/sedes/leon/oficina-equipo.webp","/img/sedes/slp/oficina-privada.webp","/img/oficina-privada/op-2.webp","/img/espacios/oficina-equipo.webp","/img/oficina-privada/op-3.webp","/img/espacios/oficina-vacia.webp","/img/oficina-privada/op-5.webp","/img/espacios/oficina-laptop.webp","/img/oficina-privada/op-6.webp"]','Oficina Privada en renta | Aldea Networking','Tu propia oficina amueblada y lista para trabajar, para equipos de 1 a 100 personas. Internet, servicios y areas comunes incluidos en Queretaro, Leon, San Luis Potosi y Aguascalientes.',NULL,NULL,1,1,1,'2026-09-23 13:54:57','Equipo trabajando en una oficina privada de Aldea','Oficina privada y amueblada\r\nCapacidad de 1 a 100+ personas\r\nTodos los servicios incluidos\r\nSalas de juntas y areas comunes\r\nContratos flexibles','Private, furnished office\r\nCapacity from 1 to 100+ people\r\nAll services included\r\nMeeting rooms and common areas\r\nFlexible contracts'),
(2,'coworking','Coworking','Coworking','Trabaja desde nuestras áreas compartidas y disfruta de las instalaciones y servicios de Aldea.','Work from our shared areas and enjoy all of Aldea''s facilities and services.','Trabaja donde quieras, cuando quieras. Un ambiente colaborativo con internet de alta velocidad, cafe, salas de juntas y una comunidad de empresas que crece contigo.',NULL,'["Acceso a espacios compartidos","Internet de alta velocidad","Cafe, te y amenidades","Horas de sala de juntas","Comunidad y networking"]',NULL,'/img/sedes/ags/coworking.webp','["/img/sedes/ags/coworking.webp","/img/sedes/leon/coworking.webp","/img/sedes/leon/coworking-cafe.webp","/img/sedes/slp/lounge.webp","/img/sedes/ags/comunidad.webp","/img/sedes/slp/cabina.webp","/img/sedes/leon/pasillo-plantas.webp","/img/wp/2025/07/11-1.webp","/img/wp/2025/07/1-2-e1756141254159.webp","/img/wp/2025/07/9-2.webp","/img/wp/2025/05/IMG_0093.webp","/img/wp/2025/07/2-2.webp","/img/wp/2025/07/10-2.webp"]','Coworking en renta | Aldea Networking','Espacios de coworking con internet, salas de juntas y servicios incluidos en Queretaro, Leon, San Luis Potosi y Aguascalientes. Membresias desde 1 mes.',NULL,NULL,1,2,1,'2026-09-23 13:54:57','Personas trabajando en el area de coworking de Aldea','Acceso a espacios compartidos\r\nInternet de alta velocidad\r\nCafe, te y amenidades\r\nHoras de sala de juntas\r\nComunidad y networking','Access to shared spaces\r\nHigh-speed internet\r\nCoffee, tea and amenities\r\nMeeting-room hours\r\nCommunity and networking'),
(3,'domicilio-virtual','Domicilio Virtual','Virtual Address','Domicilio fiscal y comercial para tu empresa, con recepción de correspondencia y servicios adicionales sin necesidad de una oficina permanente.','A registered business address with mail handling and extra services, without a permanent office.','Da a tu empresa una direccion profesional sin necesidad de una oficina fisica. Recibimos tu paqueteria y correspondencia, y tienes acceso a salas de juntas por hora cuando las necesites.',NULL,'["Domicilio fiscal y comercial","Recepcion de paqueteria","Uso de salas por hora","Imagen profesional","Acceso a la comunidad"]',NULL,'/img/sedes/ags/recepcion.webp','["/img/sedes/ags/recepcion.webp","/img/sedes/slp/recepcion.webp","/img/sedes/leon/recepcion.webp","/img/sedes/qro/recepcion.webp","/img/wp/2025/05/Sala-de-juntas-4.webp","/img/wp/2025/05/IMG_9553.webp","/img/sol-virtual.webp","/img/loc-qro.webp"]','Domicilio Virtual y domicilio fiscal | Aldea Networking','Domicilio fiscal y comercial para tu empresa con recepcion de correspondencia y acceso a salas de juntas en Queretaro, Leon, San Luis Potosi y Aguascalientes.',NULL,NULL,1,4,1,'2026-09-23 13:54:57','Recepcion de Aldea','Domicilio fiscal y comercial\r\nRecepcion de paqueteria\r\nUso de salas por hora\r\nImagen profesional\r\nAcceso a la comunidad','Business and tax address\r\nParcel reception\r\nHourly meeting-room use\r\nProfessional image\r\nAccess to the community'),
(4,'escritorio-privado','Escritorio Privado','Private Desk','Tu escritorio fijo y exclusivo dentro de un área de trabajo compartida.','Your own fixed desk inside a shared working area.','Tu lugar fijo dentro de un espacio compartido. Un escritorio dedicado y ergonomico con todas las amenidades incluidas, ideal para quienes buscan constancia y un entorno profesional sin una oficina completa.',NULL,'["Escritorio fijo y equipado","Entorno profesional","Amenidades incluidas","Acceso a salas de juntas","Ideal para individuos"]',NULL,'/img/sedes/leon/escritorio-privado.webp','["/img/sedes/leon/escritorio-privado.webp","/img/sedes/ags/escritorios.webp","/img/sedes/leon/escritorio-miembro.webp","/img/sedes/ags/equipo.webp","/img/wp/2025/07/8-4.webp","/img/wp/2025/07/1-4.webp","/img/wp/2025/07/7-4.webp","/img/wp/2025/07/2-4.webp","/img/wp/2025/07/9-4.webp","/img/wp/2025/07/3-4.webp"]','Escritorio Privado en renta | Aldea Networking','Tu escritorio fijo y exclusivo dentro de las areas compartidas de Aldea, con mobiliario, internet y servicios incluidos. Desde 1 mes en Queretaro, Leon, San Luis Potosi y Aguascalientes.',NULL,NULL,1,3,1,'2026-09-23 13:54:57','Escritorios privados asignados dentro de una zona compartida de Aldea','Escritorio fijo y equipado\r\nEntorno profesional\r\nAmenidades incluidas\r\nAcceso a salas de juntas\r\nIdeal para individuos','Fixed, equipped desk\r\nProfessional environment\r\nAmenities included\r\nAccess to meeting rooms\r\nIdeal for individuals'),
(5,'oficinas-personalizadas','Oficinas Personalizadas','Custom Offices','Disenamos el espacio a la medida de tu empresa, con la capacidad y servicios que necesitas.','We design the space to fit your company.','Cuando necesitas algo unico, lo construimos contigo. Disenamos la distribucion, capacidad y servicios de tu oficina a la medida de tu operacion y tu marca.',NULL,'["Diseno a la medida","Capacidad y layout flexible","Branding de tu empresa","Servicios a medida","Escalable"]',NULL,'/img/espacio.webp','["/img/wp/2025/07/14.webp","/img/wp/2025/07/1-5.webp","/img/wp/2025/07/15.webp","/img/wp/2025/07/3-5.webp","/img/wp/2025/07/2-5.webp","/img/wp/2025/07/4-5.webp"]',NULL,NULL,NULL,NULL,0,5,0,'2026-08-21 11:53:16','','Diseno a la medida\r\nCapacidad y layout flexible\r\nBranding de tu empresa\r\nServicios a medida\r\nEscalable','Custom design\r\nFlexible capacity and layout\r\nYour company''s branding\r\nTailored services\r\nScalable');
